73→fn files_under(dir: &Path) -> Vec<PathBuf> {
74→    let mut found = Vec::new();
75→    for entry in std::fs::read_dir(dir).expect("directory reads") {
76→        let path = entry.expect("entry reads").path();
77→        if path.is_dir() {
78→            found.extend(files_under(&path));
79→        } else {
80→            found.push(path);
81→        }
82→    }
83→    found.sort();
84→    found
85→}
