87→fn is_local_part(byte: u8) -> bool {
88→    byte.is_ascii_alphanumeric() || b"._%+-".contains(&byte)
89→}
90→
91→fn is_domain_part(byte: u8) -> bool {
92→    byte.is_ascii_alphanumeric() || b".-".contains(&byte)
93→}
94→
95→/// End (exclusive) of the longest `[A-Za-z0-9.-]+\.[A-Za-z]{2,}` prefix of `domain`.
96→fn domain_end(domain: &[u8]) -> Option<usize> {
97→    (3..=domain.len()).rev().find(|&end| {
98→        let head = &domain[..end];
99→        let letters = head
100→            .iter()
101→            .rev()
102→            .take_while(|b| b.is_ascii_alphabetic())
103→            .count();
104→        letters >= 2 && end > letters + 1 && head[end - letters - 1] == b'.'
105→    })
106→}
107→
108→/// Every match of `[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}` in `text`.
109→fn email_matches(text: &[u8]) -> Vec<&[u8]> {
110→    let mut matches = Vec::new();
111→    let mut cursor = 0;
112→    while let Some(at) = text[cursor..]
113→        .iter()
114→        .position(|b| *b == b'@')
115→        .map(|i| i + cursor)
116→    {
117→        let start = text[..at]
118→            .iter()
119→            .rposition(|b| !is_local_part(*b))
120→            .map_or(0, |i| i + 1)
121→            .max(cursor);
122→        let run = text[at + 1..]
123→            .iter()
124→            .take_while(|b| is_domain_part(**b))
125→            .count();
126→        match domain_end(&text[at + 1..at + 1 + run]) {
127→            Some(end) if start < at => {
128→                matches.push(&text[start..at + 1 + end]);
129→                cursor = at + 1 + end;
130→            }
131→            _ => cursor = at + 1,
132→        }
133→    }
134→    matches
135→}
