176→fn replay(path: &Path) -> (Vec<RawRecord>, Vec<Event>) {
177→    let mut source = JsonlSource::open(path, &IngestConfig::default()).expect("fixture opens");
178→    let version = mapping_version_of(path).expect("capture header is readable");
179→    let mut mapper = Mapper::new(SessionMeta::root(source.root_session_id().clone()), version);
180→    let mut records = Vec::new();
181→    for _ in 0..100_000 {
182→        records.extend(source.next_batch().expect("batch reads"));
183→        if source.at_eof() {
184→            records.extend(source.drain_partial());
185→            break;
186→        }
187→    }
188→    let events = records.iter().flat_map(|r| mapper.map(r)).collect();
189→    (records, events)
190→}
